CREATE TABLE IF NOT EXISTS acl_user(id BIGINT PRIMARY KEY AUTO_INCREMENT,username VARCHAR(80) NOT NULL UNIQUE,password VARCHAR(120) NOT NULL,real_name VARCHAR(80),email VARCHAR(160),phone VARCHAR(30),status INT DEFAULT 1);
CREATE TABLE IF NOT EXISTS acl_role(id BIGINT PRIMARY KEY AUTO_INCREMENT,role_name VARCHAR(80) NOT NULL UNIQUE,description VARCHAR(180),status INT DEFAULT 1);
CREATE TABLE IF NOT EXISTS acl_resource(id BIGINT PRIMARY KEY AUTO_INCREMENT,parent_id BIGINT DEFAULT 0,resource_name VARCHAR(80),code VARCHAR(160) NOT NULL UNIQUE,kind INT DEFAULT 3,url VARCHAR(180),sort_order INT DEFAULT 0,status INT DEFAULT 1);
CREATE TABLE IF NOT EXISTS acl_member(left_id BIGINT NOT NULL,right_id BIGINT NOT NULL,PRIMARY KEY(left_id,right_id),FOREIGN KEY(left_id) REFERENCES acl_user(id) ON DELETE CASCADE,FOREIGN KEY(right_id) REFERENCES acl_role(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS acl_grant(left_id BIGINT NOT NULL,right_id BIGINT NOT NULL,PRIMARY KEY(left_id,right_id),FOREIGN KEY(left_id) REFERENCES acl_role(id) ON DELETE CASCADE,FOREIGN KEY(right_id) REFERENCES acl_resource(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS team(dept_id BIGINT PRIMARY KEY,code VARCHAR(40) NOT NULL UNIQUE,label VARCHAR(80) NOT NULL,city VARCHAR(60),budget_code VARCHAR(40));
CREATE TABLE IF NOT EXISTS person(staff_id BIGINT PRIMARY KEY,badge VARCHAR(40) NOT NULL UNIQUE,full_name VARCHAR(80) NOT NULL,position VARCHAR(80),lead_id BIGINT,start_date DATE,wage DECIMAL(12,2) DEFAULT 0,bonus DECIMAL(12,2) DEFAULT 0,team_ref BIGINT NOT NULL,active INT DEFAULT 1,FOREIGN KEY(team_ref) REFERENCES team(dept_id));
CREATE TABLE IF NOT EXISTS login_account(id BIGINT PRIMARY KEY AUTO_INCREMENT,login_name VARCHAR(80) NOT NULL UNIQUE,secret VARCHAR(120) NOT NULL,mailbox VARCHAR(160) NOT NULL UNIQUE,staff_id BIGINT,state INT DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(staff_id) REFERENCES person(staff_id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS vendor(id BIGINT PRIMARY KEY,label VARCHAR(80) NOT NULL);
CREATE TABLE IF NOT EXISTS goods(id BIGINT PRIMARY KEY,title VARCHAR(80) NOT NULL,unit_price DECIMAL(12,2));
CREATE TABLE IF NOT EXISTS buyer(id BIGINT PRIMARY KEY,label VARCHAR(80) NOT NULL,city VARCHAR(60));
CREATE TABLE IF NOT EXISTS vendor_goods(vendor_id BIGINT,goods_id BIGINT,PRIMARY KEY(vendor_id,goods_id),FOREIGN KEY(vendor_id) REFERENCES vendor(id),FOREIGN KEY(goods_id) REFERENCES goods(id));
CREATE TABLE IF NOT EXISTS inventory(id BIGINT PRIMARY KEY,goods_id BIGINT NOT NULL,vendor_id BIGINT NOT NULL,serial_code VARCHAR(60) UNIQUE,FOREIGN KEY(goods_id) REFERENCES goods(id),FOREIGN KEY(vendor_id) REFERENCES vendor(id));
CREATE TABLE IF NOT EXISTS purchase(id BIGINT PRIMARY KEY,item_id BIGINT NOT NULL UNIQUE,buyer_id BIGINT NOT NULL,paid DECIMAL(12,2),sold_on DATE,FOREIGN KEY(item_id) REFERENCES inventory(id),FOREIGN KEY(buyer_id) REFERENCES buyer(id));
CREATE TABLE IF NOT EXISTS service_event(id BIGINT PRIMARY KEY,vendor_id BIGINT NOT NULL,buyer_id BIGINT NOT NULL,description VARCHAR(240),happened_on DATE,FOREIGN KEY(vendor_id) REFERENCES vendor(id),FOREIGN KEY(buyer_id) REFERENCES buyer(id));
CREATE TABLE IF NOT EXISTS learner(id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(80) NOT NULL,age INT,email VARCHAR(160),major VARCHAR(80),score DOUBLE,version INT DEFAULT 0 NOT NULL,deleted INT DEFAULT 0 NOT NULL,create_time TIMESTAMP,update_time TIMESTAMP);
